// src/report.ts

import type { Row, Summary } from "./types.ts";

export function ordersSummary0(rows: Row[], from: Date, to: Date): Summary {
  const inRange = rows.filter((row) => row.at >= from && row.at < to && row.kind === "orders");
  const total = inRange.reduce((sum, row) => sum + row.amountCents, 0);
  return { kind: "orders", count: inRange.length, totalCents: total, averageCents: inRange.length ? Math.round(total / inRange.length) : 0 };
}

